import random, itertools
def dp_count(n, Y):
    INF, NEG = n+1, 0
    YY = [0]*(n+2); YY[0]=INF; YY[n+1]=NEG
    for x in range(1,n+1): YY[x]=Y[x-1]
    def valid(a,b):
        ya=YY[a]; yb=YY[b]
        ys=[YY[x] for x in range(a+1,b) if yb<YY[x]<ya]
        m=len(ys)
        if m==0: return True
        sm=[NEG]*(m+1)
        for i in range(m-1,-1,-1): sm[i]=max(ys[i],sm[i+1])
        pm=INF
        for i in range(m):
            if pm>ys[i] and sm[i+1]<ys[i]: return False
            pm=min(pm,ys[i])
        return True
    f=[0]*(n+2)
    for b in range(1,n+1):
        if valid(0,b): f[b]=1
        for a in range(1,b):
            if YY[a]>YY[b] and f[a] and valid(a,b): f[b]+=f[a]
    ans = 1 if valid(0,n+1) else 0
    for a in range(1,n+1):
        if f[a] and valid(a,n+1): ans+=f[a]
    return ans
