class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_b = [[] for _ in range(n + 1)]
        for x, y in conflictingPairs:
            a, b = min(x, y), max(x, y)
            by_b[b].append(a)
        gain = [0] * (n + 2)
        m1 = 0
        m2 = 0
        total = 0
        for r in range(1, n + 1):
            for x in by_b[r]:
                if x >= m1:
                    m2 = m1
                    m1 = x
                elif x > m2:
                    m2 = x
            total += r - m1
            if m1 > 0 and m2 < m1:
                gain[m1] += m1 - m2
