import itertools, math
def lis(seq, cond=None):
    # longest increasing
    import bisect
    t=[]
    for v in seq:
        i=bisect.bisect_left(t,v)
        if i==len(t): t.append(v)
        else: t[i]=v
    return len(t)
def lds(seq):
    return lis([-v for v in seq])
def hook(shape):
    n=sum(shape)
    conj=[sum(1 for r in shape if r>j) for j in range(shape[0])]
    h=1
    for i,r in enumerate(shape):
        for j in range(r):
            h*= (r-j-1)+(conj[j]-i-1)+1
    return math.factorial(n)//h
