        if cur==lam: return 1
        tot=0
        for i in range(n):
            if cur[i]<lam[i] and (i==0 or cur[i-1]>cur[i]):
                c=list(cur); c[i]+=1; tot+=f(tuple(c))
        return tot
    return f(tuple(nu))
