            nu=[A]+cur
            lam=tuple(A-nu[B-1-k] for k in range(B))
            G=0
            for k in range(B):
                if lam[k]>0 and (k==B-1 or lam[k+1]<lam[k]):
                    kap=list(lam); kap[k]-=1
                    if sum(1 for x in kap if x>0)<=B-2:
                        G+=F(tuple(kap))
            if G:
                nup=tuple([A-1]+cur)
                good=(good+F(nup)*G)%M
            return
        for v in range(maxv,-1,-1):
            cur.append(v); gen(i+1,v,cur); cur.pop()
