def fast(n,A):
    L=[0]*n; seen=set()
    for i in range(n):
        seen.add(A[i]); L[i]=len(seen)
    R=[0]*(n+1); seen=set()
    for k in range(n-1,-1,-1):
        seen.add(A[k]); R[k]=len(seen)
    par=list(range(n+1))
    def find(x):
        r=x
        while par[r]!=r: r=par[r]
        while par[x]!=r:
            par[x],x=r,par[x]
        return r
    prev=[-1]*n; diff=[0]*n
    empty=True; F=0; last=-1; lastVal=0
    last_occ={}; best=-1
    for j in range(1,n-1):
        x=j-1; v=L[x]
        if empty:
            empty=False; F=v; last=x; lastVal=v; prev[x]=-1
        else:
            while not empty and lastVal<=v:
                l=last; p=prev[l]
                par[l]=l+1
                if p==-1:
                    empty=True
                else:
                    lastVal+=diff[l]; last=p
            if empty:
                empty=False; F=v; last=x; lastVal=v; prev[x]=-1
            else:
                prev[x]=last; diff[x]=lastVal-v; last=x; lastVal=v
        q=last_occ.get(A[j],-1); last_occ[A[j]]=j
        lo=q if q>0 else 0
        k=find(lo)
        lastVal+=1
        p=prev[k]
        if p==-1:
            F+=1
        else:
            diff[k]-=1
            if diff[k]==0:
