class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        N = L + 1
        C = [[0] * (N + 1) for _ in range(N + 1)]
        for i in range(N + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        def steps(v):
            t = 0
            while v != 1:
                v = bin(v).count('1')
                t += 1
            return t

        cnt = [0] * (L + 1)
        ones = 0
        for i in range(L):
            if s[i] == '1':
                rem = L - i - 1
                for c in range(ones, ones + rem + 1):
                    need = c - ones
                    if need <= rem:
                        cnt[c] = (cnt[c] + C[rem][need]) % MOD
                ones += 1
        ans = 0
        for c in range(1, L + 1):
            if c == 1:
                good = True
            else:
                good = steps(c) + 1 <= k
            if good:
                ans = (ans + cnt[c]) % MOD
        return ans

