import sys
def main():
    d=sys.stdin.read().split()
    n,m=int(d[0]),int(d[1])
    A=[0]*n
    for i in range(m):
        u=int(d[2+2*i])-1; v=int(d[3+2*i])-1
        A[u]|=1<<v; A[v]|=1<<u
    rows=A[:]
    piv=[]
    rank=0
    for c in range(n):
        r=-1
        for i in range(rank,n):
            if rows[i]>>c&1:
                r=i;break
        if r<0: continue
        rows[rank],rows[r]=rows[r],rows[rank]
        for i in range(n):
            if i!=rank and rows[i]>>c&1:
                rows[i]^=rows[rank]
        piv.append(c)
        rank+=1
    pivset=set(piv)
    basis=[]
    for f in range(n):
        if f in pivset: continue
        x=[0]*n
        x[f]=1
        for k,p in enumerate(piv):
            x[p]=(rows[k]>>f)&1
        basis.append(x)
    X=[0]*n
    for j,b in enumerate(basis):
        for i in range(n):
            if b[i]: X[i]|=1<<j
    if any(v==0 for v in X):
        print("No")
    else:
        print("Yes")
        print(*X)
