from functools import lru_cache
from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        O = (n + 1) // 2
        E = n // 2

        @lru_cache(None)
        def cnt(o, e, p):
            # p: -1 start, 0 last even, 1 last odd
            if o + e == 0:
                return 1
            if p == -1:
                r = 0
                if e > 0:
                    r += e * cnt(o, e - 1, 0)
                if o > 0:
                    r += o * cnt(o - 1, e, 1)
                return r
            if p == 1:
                return e * cnt(o, e - 1, 0) if e > 0 else 0
            return o * cnt(o - 1, e, 1) if o > 0 else 0

        if k > cnt(O, E, -1):
            return []
        res = []
        used = [False] * (n + 1)
        o, e = O, E
        prev = -1
        for _ in range(n):
            for x in range(1, n + 1):
                if used[x]:
                    continue
                if prev != -1 and (x % 2) == prev:
                    continue
                no, ne = o, e
                if x % 2 == 1:
                    no -= 1
                else:
                    ne -= 1
                c = cnt(no, ne, x % 2)
                if k <= c:
                    used[x] = True
                    res.append(x)
                    o, e = no, ne
                    prev = x % 2
                    break
                k -= c
        return res

