class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        w = []
        for j in range(h):
            i2 = n - 1 - j
            if i2 == j:
                wt = pow(10, j, k)
            else:
                wt = (pow(10, j, k) + pow(10, i2, k)) % k
            w.append(wt)
        S = [None] * (h + 1)
        S[h] = {0}
        for j in range(h - 1, -1, -1):
            lo = 1 if j == 0 else 0
            vals = {(d * w[j]) % k for d in range(lo, 10)}
            nxt = S[j + 1]
            S[j] = {(a + s) % k for a in vals for s in nxt}
        if 0 not in S[0]:
            return ""
        cur = 0
        digits = []
        for j in range(h):
            lo = 1 if j == 0 else 0
            for d in range(9, lo - 1, -1):
                r = (cur + d * w[j]) % k
                if (-r) % k in S[j + 1]:
                    digits.append(d)
                    cur = r
                    break
        if n % 2 == 1:
            full = digits + digits[-2::-1]
        else:
            full = digits + digits[::-1]
        return ''.join(map(str, full))

