class Solution:
    def makeStringGood(self, s: str) -> int:
        INF = float('inf')
        K = 8
        n = len(s)
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        M = max(cnt)
        best = INF
        for f in range(1, min(n, M + 26) + 1):
            dp = [INF] * (K + 1)
            dp[0] = 0
            for c in cnt:
                lim = [INF] * (K + 1)
                for i in range(K + 1):
                    d = dp[i]
                    if d == INF:
                        continue
                    a = c + i
                    j = a if a < K else K
                    if d + a < lim[j]:
                        lim[j] = d + a
                    if a < f:
                        if d + f - a < lim[0]:
                            lim[0] = d + f - a
                    else:
                        L = a - f
                        if L > K:
                            L = K
                        if d + a - f < lim[L]:
                            lim[L] = d + a - f
                run = INF
                new = [INF] * (K + 1)
                for o in range(K, -1, -1):
                    if lim[o] < run:
                        run = lim[o]
                    new[o] = run
                dp = new
            if dp[0] < best:
                best = dp[0]
        return int(best)

