    for f in range(1,fmax_fn(n,M)+1):
        dp=[INF]*(n+1); dp[0]=0
        for c in cnt:
            new=[INF]*(n+1)
            # best limit array
            lim=[INF]*(n+1)
            for i in range(n+1):
                if dp[i]==INF: continue
                a=c+i
                # final 0
                if a<=n and dp[i]+a<lim[a]: lim[a]=dp[i]+a
                if a<f:
