import heapq, random, functools
def solve(n, a):
    def pref(arr):
        res = [0]*(len(arr)+1)
        low=[]; high=[]; ls=0; hs=0
        for i,x in enumerate(arr):
            # insert x
            heapq.heappush(low, -x); ls += x
            m = -heapq.heappop(low); ls -= m
            heapq.heappush(high, m); hs += m
            if len(high) > len(low):
                t = heapq.heappop(high); hs -= t
                heapq.heappush(low, -t); ls += t
            k=i+1
            if k%2==0: res[k]=hs-ls
        return res
    F = pref(a)
    if n%2==0: return F[n]
    G = pref(a[::-1])  # G[L] = value of suffix of length L
    best=None
    for k in range(0,n,2):
        v = F[k] + G[n-1-k]
        if best is None or v>best: best=v
    return best
def brute(a):
    @functools.lru_cache(None)
    def f(t):
        if len(t)<=1: return 0
        b=-1
        for i in range(len(t)-1):
            nt=t[:i]+t[i+2:]
            b=max(b,abs(t[i]-t[i+1])+f(nt))
        return b
    return f(tuple(a))
