from bisect import bisect_left, bisect_right

def occ(x, s):
    n, m = len(s), len(x)
    if m == 0:
        return list(range(n + 1))
    t = x + '#' + s
    L = len(t)
    pi = [0] * L
    k = 0
    for q in range(1, L):
        while k and t[q] != t[k]:
            k = pi[k - 1]
        if t[q] == t[k]:
            k += 1
        pi[q] = k
    res = []
    for q in range(m + 1, L):
        if pi[q] == m:
            res.append(q - 2 * m)
    return res

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        i1 = p.index('*')
        i2 = p.index('*', i1 + 1)
        a = p[:i1]
        b = p[i1 + 1:i2]
        c = p[i2 + 1:]
        A = occ(a, s)
        B = occ(b, s)
        C = occ(c, s)
        if not A or not C:
            return -1
        la, lb, lc = len(a), len(b), len(c)
        best = -1
        for k in B:
            idx = bisect_right(A, k - la) - 1
            if idx < 0:
                continue
            i = A[idx]
            j = bisect_left(C, k + lb)
            if j >= len(C):
                continue
            m = C[j]
            length = m + lc - i
            if best < 0 or length < best:
                best = length
        return best

