class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        def ok(reach):
            for i in range(n):
                if not (reach[i] >> nums[i]) & 1:
                    return False
            return True
        reach = [1] * n
        if ok(reach):
            return 0
        for k, (l, r, v) in enumerate(queries):
            for i in range(l, r + 1):
                cap = nums[i]
                reach[i] = (reach[i] | (reach[i] << v)) & ((1 << (cap + 1)) - 1)
            if ok(reach):
                return k + 1
        return -1

