import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        N = 10000
        sieve = [True]*N
        sieve[0]=sieve[1]=False
        for i in range(2,int(N**0.5)+1):
            if sieve[i]:
                for j in range(i*i,N,i): sieve[j]=False
        def isp(x): return x>=2 and sieve[x]
        if isp(n) or isp(m): return -1
        k = len(str(n))
        p = [10**i for i in range(k)]
        INF = float('inf')
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, x = heapq.heappop(pq)
            if d != dist.get(x): continue
            if x == m: return d
            for pw in p:
                dig = (x//pw)%10
                for y in ([x+pw] if dig<9 else []) + ([x-pw] if dig>0 else []):
                    if isp(y): continue
                    nd = d + y
                    if nd < dist.get(y, INF):
                        dist[y] = nd
                        heapq.heappush(pq, (nd, y))
        return -1

