import numpy as np
class Solution:
    def beautifulSplits(self, nums):
        a = np.array(nums, dtype=np.int64)
        n = len(a)
        if n < 3:
            return 0
        def lcp0(i):
            eq = a[:n-i] == a[i:]
            if eq.all():
                return n - i
            return int(np.argmin(eq))
        P = np.zeros(n + 2, dtype=np.int64)
        total = 0
        for i in range(n - 1, -1, -1):
            R = np.zeros(n + 2, dtype=np.int64)
            if i + 1 <= n - 1:
                R[i+1:n] = (a[i+1:n] == a[i]) * (P[i+2:n+1] + 1)
            if 1 <= i <= n - 2:
                lo, hi = i + 1, n - 1
                jj = np.arange(lo, hi + 1)
                B = (jj <= (n + i) // 2) & (R[lo:hi+1] >= jj - i)
                if lcp0(i) >= i:
                    A = jj >= 2 * i
                else:
                    A = np.zeros(len(jj), dtype=bool)
                total += int(np.sum(A | B))
            P = R
        return total

