import heapq
from typing import List
class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        radj = [[] for _ in range(n)]
        for a, b, w in edges:
            radj[b].append((a, w))
        INF = float('inf')
        best = [INF] * n
        best[0] = 0
        pq = [(0, 0)]
        while pq:
            d, v = heapq.heappop(pq)
            if d > best[v]:
                continue
            for u, w in radj[v]:
                nd = max(d, w)
                if nd < best[u]:
                    best[u] = nd
                    heapq.heappush(pq, (nd, u))
        if any(x == INF for x in best):
            return -1
        return max(best)

