from typing import List
class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2
        INF = float('inf')
        dp = {}
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[(a, b)] = cost[0][a] + cost[n-1][b]
        for i in range(1, m):
            nd = {}
            for a in range(3):
                for b in range(3):
                    if a == b:
                        continue
                    best = INF
                    for (pa, pb), v in dp.items():
                        if pa != a and pb != b and v < best:
                            best = v
                    nd[(a, b)] = best + cost[i][a] + cost[n-1-i][b]
            dp = nd
        return int(min(dp.values()))

