class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        total = 0
        for i, ch in enumerate(s):
            c = ord(ch) - 97
            m = 25 - c
            if stacks[m]:
                j = stacks[m].pop()
                total += i - j
            else:
                stacks[c].append(i)
        return total

